-- Curate Biology and Chemistry starter quizzes with topic-specific application
-- questions, bilingual answer choices, and short explanations. These catalog
-- updates seed as drafts; existing published questions are not modified.
UPDATE starter_content_catalog AS c
SET quiz_en=v.quiz_en,
    quiz_fil=v.quiz_fil,
    explanation_en=v.explanation_en,
    explanation_fil=v.explanation_fil,
    options=v.options::jsonb
FROM (VALUES
 ('starter-biology-cell', $$A sample from an organism is examined under a microscope. What basic unit should be visible?$$, $$Sinusuri sa mikroskopyo ang isang sample mula sa organismo. Anong pangunahing yunit ang dapat makita?$$, $$Cells are the basic structural units of living organisms.$$ , $$Ang mga selula ang pangunahing yunit na bumubuo sa mga organismo.$$ , $$[{"en":"Cells","fil":"Mga selula","correct":true},{"en":"Organs","fil":"Mga organo","correct":false},{"en":"Ecosystems","fil":"Mga ecosystem","correct":false},{"en":"Molecules only","fil":"Mga molekula lamang","correct":false}]$$),
 ('starter-biology-nucleus', $$A cell needs to store most of its hereditary instructions. Which structure does this in many cells?$$, $$Kailangang mag-imbak ng selula ng karamihan sa namamanang tagubilin nito. Aling bahagi ang gumagawa nito sa maraming selula?$$, $$In many cells, most DNA is stored in the nucleus.$$ , $$Sa maraming selula, iniimbak sa nucleus ang karamihan ng DNA.$$ , $$[{"en":"Nucleus","fil":"Nucleus","correct":true},{"en":"Cell membrane","fil":"Lamad ng selula","correct":false},{"en":"Cytoplasm","fil":"Cytoplasm","correct":false},{"en":"Chloroplast","fil":"Chloroplast","correct":false}]$$),
 ('starter-biology-membrane', $$A cell must regulate which substances enter or leave it. Which structure performs this boundary role?$$, $$Kailangang kontrolin ng selula kung aling mga sangkap ang pumapasok o lumalabas. Aling bahagi ang nagsisilbing hangganan nito?$$, $$The cell membrane helps control movement into and out of a cell.$$ , $$Tumutulong ang lamad ng selula na kontrolin ang pagpasok at paglabas ng mga sangkap.$$ , $$[{"en":"Cell membrane","fil":"Lamad ng selula","correct":true},{"en":"Nucleus","fil":"Nucleus","correct":false},{"en":"Mitochondrion","fil":"Mitochondrion","correct":false},{"en":"Cell wall of an animal cell","fil":"Cell wall ng selula ng hayop","correct":false}]$$),
 ('starter-biology-cytoplasm', $$Many chemical processes take place in the material filling the inside of a cell. What is this material called?$$, $$Maraming prosesong kemikal ang nagaganap sa materyal na pumupuno sa loob ng selula. Ano ang tawag dito?$$, $$The cytoplasm is the material inside a cell where many processes occur.$$ , $$Ang cytoplasm ang materyal sa loob ng selula kung saan nagaganap ang maraming proseso.$$ , $$[{"en":"Cytoplasm","fil":"Cytoplasm","correct":true},{"en":"Nucleus","fil":"Nucleus","correct":false},{"en":"Cell membrane","fil":"Lamad ng selula","correct":false},{"en":"Chromosome pair outside the cell","fil":"Pares ng chromosome sa labas ng selula","correct":false}]$$),
 ('starter-biology-dna', $$Offspring inherit biological instructions from their parents. Which molecule carries these instructions?$$, $$Namamana ng supling ang mga biyolohikal na tagubilin mula sa mga magulang. Aling molekula ang nagdadala ng mga tagubiling ito?$$, $$DNA carries inherited instructions used in organism growth and functioning.$$ , $$Nagdadala ang DNA ng namamanang tagubilin para sa paglaki at paggana ng organismo.$$ , $$[{"en":"DNA","fil":"DNA","correct":true},{"en":"Glucose","fil":"Glucose","correct":false},{"en":"Water","fil":"Tubig","correct":false},{"en":"Cell membrane","fil":"Lamad ng selula","correct":false}]$$),
 ('starter-biology-gene', $$A researcher studies a short DNA section that contains instructions for a functional product. What is that section called?$$, $$Pinag-aaralan ng mananaliksik ang maikling bahagi ng DNA na may tagubilin para sa isang gumaganang produkto. Ano ang tawag sa bahaging ito?$$, $$A gene is a section of DNA containing instructions for a functional product.$$ , $$Ang gene ay bahagi ng DNA na may tagubilin para sa isang gumaganang produkto.$$ , $$[{"en":"A gene","fil":"Gene","correct":true},{"en":"A tissue","fil":"Tissue","correct":false},{"en":"A lipid","fil":"Lipid","correct":false},{"en":"An organ system","fil":"Organ system","correct":false}]$$),
 ('starter-biology-mitochondria', $$A cell breaks down food molecules and releases usable energy. Which organelles help with this process?$$, $$Binabaklas ng selula ang mga molekula ng pagkain at naglalabas ng magagamit na enerhiya. Aling mga organelle ang tumutulong sa prosesong ito?$$, $$Mitochondria help cells release usable energy from food molecules.$$ , $$Tumutulong ang mitochondria na maglabas ng magagamit na enerhiya mula sa mga molekula ng pagkain.$$ , $$[{"en":"Mitochondria","fil":"Mitochondria","correct":true},{"en":"Chloroplasts","fil":"Chloroplasts","correct":false},{"en":"Cell membranes","fil":"Mga lamad ng selula","correct":false},{"en":"Ribosomes in the bloodstream","fil":"Ribosome sa daluyan ng dugo","correct":false}]$$),
 ('starter-biology-chloroplast', $$A plant cell captures light to carry out photosynthesis. Where does this process take place?$$, $$Kumukuha ng liwanag ang selula ng halaman upang maganap ang photosynthesis. Saan nagaganap ang prosesong ito?$$, $$Photosynthesis takes place in chloroplasts in plant cells.$$ , $$Nagaganap ang photosynthesis sa mga chloroplast ng selula ng halaman.$$ , $$[{"en":"Chloroplasts","fil":"Chloroplasts","correct":true},{"en":"Mitochondria only","fil":"Mitochondria lamang","correct":false},{"en":"The nucleus","fil":"Nucleus","correct":false},{"en":"The cell membrane","fil":"Lamad ng selula","correct":false}]$$),
 ('starter-biology-photosynthesis', $$A plant uses light, water, and carbon dioxide to make sugar. What process is it carrying out?$$, $$Gumagamit ang halaman ng liwanag, tubig, at carbon dioxide upang gumawa ng asukal. Anong proseso ang nagaganap?$$, $$Photosynthesis uses light energy to make sugars from water and carbon dioxide.$$ , $$Ginagamit ng photosynthesis ang enerhiya ng liwanag upang gumawa ng asukal mula sa tubig at carbon dioxide.$$ , $$[{"en":"Photosynthesis","fil":"Photosynthesis","correct":true},{"en":"Cellular respiration","fil":"Cellular respiration","correct":false},{"en":"Digestion","fil":"Digestion","correct":false},{"en":"Fermentation in all plant cells","fil":"Fermentation sa lahat ng selula ng halaman","correct":false}]$$),
 ('starter-biology-respiration', $$A cell needs to release energy stored in food so it can perform its functions. Which process does this?$$, $$Kailangang maglabas ng selula ng enerhiyang nakaimbak sa pagkain upang magampanan nito ang mga tungkulin. Aling proseso ang gumagawa nito?$$, $$Cellular respiration releases usable energy from food molecules.$$ , $$Naglalabas ang cellular respiration ng magagamit na enerhiya mula sa mga molekula ng pagkain.$$ , $$[{"en":"Cellular respiration","fil":"Cellular respiration","correct":true},{"en":"Photosynthesis","fil":"Photosynthesis","correct":false},{"en":"Pollination","fil":"Pollination","correct":false},{"en":"Diffusion of sunlight","fil":"Diffusion ng sikat ng araw","correct":false}]$$),
 ('starter-biology-tissues', $$Similar cells work together to perform a shared function. What level of organization do they form?$$, $$Nagtutulungan ang magkakatulad na selula upang gampanan ang iisang tungkulin. Anong antas ng organisasyon ang nabubuo nila?$$, $$A tissue is a group of similar cells working together.$$ , $$Ang tissue ay pangkat ng magkakatulad na selulang nagtutulungan.$$ , $$[{"en":"A tissue","fil":"Tissue","correct":true},{"en":"An organ system","fil":"Organ system","correct":false},{"en":"An ecosystem","fil":"Ecosystem","correct":false},{"en":"A population of different species","fil":"Populasyon ng magkakaibang species","correct":false}]$$),
 ('starter-biology-organs', $$Several different tissue types cooperate to carry out a body function. What structure do they form?$$, $$Nagtutulungan ang ilang magkakaibang uri ng tissue upang gampanan ang tungkulin ng katawan. Anong estruktura ang nabubuo nila?$$, $$Different tissues working together form an organ.$$ , $$Nabubuo ang organ kapag nagtutulungan ang magkakaibang tissue.$$ , $$[{"en":"An organ","fil":"Organ","correct":true},{"en":"A cell","fil":"Selula","correct":false},{"en":"A population","fil":"Populasyon","correct":false},{"en":"A molecule","fil":"Molekula","correct":false}]$$),
 ('starter-biology-organ-systems', $$The heart, blood vessels, and related organs work together to circulate blood. What level of organization is this?$$, $$Nagtutulungan ang puso, mga daluyan ng dugo, at kaugnay na mga organo upang magpaikot ng dugo. Anong antas ng organisasyon ito?$$, $$An organ system is a group of organs working together in the body.$$ , $$Ang organ system ay pangkat ng mga organong nagtutulungan sa katawan.$$ , $$[{"en":"An organ system","fil":"Organ system","correct":true},{"en":"A tissue","fil":"Tissue","correct":false},{"en":"A single cell","fil":"Iisang selula","correct":false},{"en":"A habitat","fil":"Habitat","correct":false}]$$),
 ('starter-biology-unicellular', $$A microorganism consists of only one cell. How is it classified?$$, $$Binubuo lamang ng isang selula ang mikroorganismo. Paano ito inuuri?$$, $$A unicellular organism consists of a single cell.$$ , $$Binubuo ng iisang selula ang unicellular na organismo.$$ , $$[{"en":"Unicellular","fil":"Unicellular","correct":true},{"en":"Multicellular","fil":"Multicellular","correct":false},{"en":"A tissue","fil":"Tissue","correct":false},{"en":"A population of organs","fil":"Populasyon ng mga organo","correct":false}]$$),
 ('starter-biology-multicellular', $$An organism has many cells, and different cells perform specialized roles. What term describes it?$$, $$Maraming selula ang organismo at may espesyalisadong tungkulin ang mga ito. Anong termino ang naglalarawan dito?$$, $$A multicellular organism is made of many cells that may have different roles.$$ , $$Binubuo ng maraming selulang maaaring may magkakaibang tungkulin ang multicellular na organismo.$$ , $$[{"en":"Multicellular","fil":"Multicellular","correct":true},{"en":"Unicellular","fil":"Unicellular","correct":false},{"en":"Acellular tissue","fil":"Acellular na tissue","correct":false},{"en":"A single-celled colony only","fil":"Kolonya ng iisang selula lamang","correct":false}]$$),
 ('starter-biology-pollination', $$Pollen moves from a flower’s male part to its female part. Which plant process is this?$$, $$Inilipat ang pollen mula sa bahaging lalaki ng bulaklak patungo sa bahaging babae nito. Anong proseso ng halaman ito?$$, $$Pollination transfers pollen within or between flowers and can help plants reproduce.$$ , $$Inililipat ng pollination ang pollen sa loob o pagitan ng mga bulaklak at nakatutulong sa pagpaparami ng halaman.$$ , $$[{"en":"Pollination","fil":"Pollination","correct":true},{"en":"Seed dispersal","fil":"Pagkalat ng buto","correct":false},{"en":"Germination","fil":"Pagsibol","correct":false},{"en":"Cellular respiration","fil":"Cellular respiration","correct":false}]$$),
 ('starter-biology-decomposers', $$Fungi break down dead leaves and return materials to the environment. What ecological role do they play?$$, $$Binabaklas ng fungi ang mga patay na dahon at ibinabalik ang mga materyal sa kapaligiran. Ano ang papel nila sa ecosystem?$$, $$Decomposers break down dead material and recycle nutrients.$$ , $$Binabaklas ng decomposer ang patay na materyal at ibinabalik ang mga sustansiya sa kapaligiran.$$ , $$[{"en":"Decomposers","fil":"Mga decomposer","correct":true},{"en":"Primary consumers","fil":"Mga primary consumer","correct":false},{"en":"Pollinators only","fil":"Pollinator lamang","correct":false},{"en":"Abiotic factors","fil":"Mga abiotic factor","correct":false}]$$),
 ('starter-biology-food-web', $$A diagram links several food chains in one habitat. What does the whole network represent?$$, $$Pinagdurugtong ng diagram ang ilang food chain sa iisang tirahan. Ano ang kinakatawan ng buong ugnayan?$$, $$A food web connects multiple food chains in an ecosystem.$$ , $$Pinag-uugnay ng food web ang maraming food chain sa isang ecosystem.$$ , $$[{"en":"A food web","fil":"Food web","correct":true},{"en":"A single food chain","fil":"Iisang food chain","correct":false},{"en":"A water cycle","fil":"Siklo ng tubig","correct":false},{"en":"A population pyramid only","fil":"Piramide ng populasyon lamang","correct":false}]$$),
 ('starter-biology-producers', $$A plant makes its own food using energy from sunlight. What role does it have in a food chain?$$, $$Gumagawa ng sariling pagkain ang halaman gamit ang enerhiya mula sa sikat ng araw. Ano ang papel nito sa food chain?$$, $$Producers make organic food using energy.$$ , $$Gumagawa ng organikong pagkain gamit ang enerhiya ang mga producer.$$ , $$[{"en":"Producer","fil":"Producer","correct":true},{"en":"Consumer","fil":"Consumer","correct":false},{"en":"Decomposer","fil":"Decomposer","correct":false},{"en":"Nonliving factor","fil":"Di-buhay na salik","correct":false}]$$),
 ('starter-biology-biodiversity', $$A protected forest contains many different species of plants, animals, and fungi. What does this variety describe?$$, $$Maraming magkakaibang species ng halaman, hayop, at fungi ang nasa isang protektadong gubat. Ano ang inilalarawan ng pagkakaiba-ibang ito?$$, $$Biodiversity is the variety of living things in an area or on Earth.$$ , $$Ang biodiversity ay pagkakaiba-iba ng mga may buhay sa isang lugar o sa Daigdig.$$ , $$[{"en":"Biodiversity","fil":"Biodiversity","correct":true},{"en":"Air pressure","fil":"Presyon ng hangin","correct":false},{"en":"Population density only","fil":"Densidad ng populasyon lamang","correct":false},{"en":"A single-species habitat","fil":"Tirahan ng iisang species","correct":false}]$$),
 ('starter-chemistry-matter', $$A sample has mass and occupies space. Which broad scientific category does it belong to?$$, $$May masa at sumasakop ng espasyo ang sample. Saang malawak na kategoryang pang-agham ito nabibilang?$$, $$Matter has mass and occupies space.$$ , $$May masa at sumasakop ng espasyo ang matter.$$ , $$[{"en":"Matter","fil":"Matter o materya","correct":true},{"en":"Energy only","fil":"Enerhiya lamang","correct":false},{"en":"A force","fil":"Puwersa","correct":false},{"en":"A measurement unit","fil":"Yunit ng pagsukat","correct":false}]$$),
 ('starter-chemistry-atom', $$A chemist describes the basic unit that makes up an element while retaining its chemical identity. What is it?$$, $$Inilalarawan ng chemist ang pangunahing yunit na bumubuo sa isang elemento at nagpapanatili ng pagkakakilanlang kemikal nito. Ano ito?$$, $$An atom is the basic unit of an element.$$ , $$Ang atom ang pangunahing yunit ng isang elemento.$$ , $$[{"en":"An atom","fil":"Atom","correct":true},{"en":"A mixture","fil":"Mixture","correct":false},{"en":"A cell","fil":"Selula","correct":false},{"en":"A solution only","fil":"Solusyon lamang","correct":false}]$$),
 ('starter-chemistry-proton', $$Which subatomic particle has a positive electric charge and is found in an atom’s nucleus?$$, $$Aling subatomic particle ang may positibong kargang elektriko at matatagpuan sa nucleus ng atom?$$, $$Protons have a positive charge and are located in the nucleus.$$ , $$May positibong karga ang proton at matatagpuan ito sa nucleus.$$ , $$[{"en":"Proton","fil":"Proton","correct":true},{"en":"Neutron","fil":"Neutron","correct":false},{"en":"Electron","fil":"Electron","correct":false},{"en":"Photon","fil":"Photon","correct":false}]$$),
 ('starter-chemistry-neutron', $$A particle in an atom’s nucleus has no electric charge. Which particle is it?$$, $$Walang kargang elektriko ang isang particle sa nucleus ng atom. Aling particle ito?$$, $$A neutron has no electric charge and is found in the nucleus.$$ , $$Walang kargang elektriko ang neutron at matatagpuan ito sa nucleus.$$ , $$[{"en":"Neutron","fil":"Neutron","correct":true},{"en":"Proton","fil":"Proton","correct":false},{"en":"Electron","fil":"Electron","correct":false},{"en":"Ion","fil":"Ion","correct":false}]$$),
 ('starter-chemistry-electron', $$Which subatomic particle has a negative charge and occupies regions around the nucleus?$$, $$Aling subatomic particle ang may negatibong karga at nasa mga rehiyon sa paligid ng nucleus?$$, $$Electrons have a negative charge and occupy regions around the nucleus.$$ , $$May negatibong karga ang electron at nasa mga rehiyon ito sa paligid ng nucleus.$$ , $$[{"en":"Electron","fil":"Electron","correct":true},{"en":"Proton","fil":"Proton","correct":false},{"en":"Neutron","fil":"Neutron","correct":false},{"en":"Nucleus","fil":"Nucleus","correct":false}]$$),
 ('starter-chemistry-element', $$A pure substance contains only one kind of atom. What type of substance is it?$$, $$Iisang uri lamang ng atom ang bumubuo sa purong substance. Anong uri ito?$$, $$An element is a pure substance made of one kind of atom.$$ , $$Ang elemento ay purong substance na binubuo ng iisang uri ng atom.$$ , $$[{"en":"Element","fil":"Elemento","correct":true},{"en":"Compound","fil":"Compound","correct":false},{"en":"Heterogeneous mixture","fil":"Heterogeneous mixture","correct":false},{"en":"Solution of different elements","fil":"Solusyon ng magkakaibang elemento","correct":false}]$$),
 ('starter-chemistry-compound', $$Water molecules contain hydrogen and oxygen chemically bonded in a fixed ratio. What kind of substance is water?$$, $$Magkakabigkis sa tiyak na proporsyon ang hydrogen at oxygen sa mga molekula ng tubig. Anong uri ng substance ang tubig?$$, $$A compound contains atoms of different elements chemically bonded together.$$ , $$Naglalaman ang compound ng mga atom mula sa magkakaibang elementong pinag-ugnay sa kemikal.$$ , $$[{"en":"Compound","fil":"Compound","correct":true},{"en":"Element","fil":"Elemento","correct":false},{"en":"Mechanical mixture","fil":"Mechanical mixture","correct":false},{"en":"Single atom","fil":"Iisang atom","correct":false}]$$),
 ('starter-chemistry-mixture', $$A bowl contains sand and iron filings that can be separated physically. How should the contents be classified?$$, $$May buhangin at iron filing sa mangkok at maaari silang paghiwalayin sa pisikal na paraan. Paano dapat uriin ang laman nito?$$, $$A mixture combines substances physically, so its components can often be separated physically.$$ , $$Pinagsasama ng mixture ang mga substance sa pisikal na paraan kaya madalas silang mapaghiwalay nang pisikal.$$ , $$[{"en":"A mixture","fil":"Mixture","correct":true},{"en":"A single element","fil":"Iisang elemento","correct":false},{"en":"A pure compound","fil":"Purong compound","correct":false},{"en":"A new atom","fil":"Bagong atom","correct":false}]$$),
 ('starter-chemistry-molecule', $$Two or more atoms join through chemical bonds to form one particle. What is that particle called?$$, $$Nag-uugnay sa pamamagitan ng chemical bond ang dalawa o higit pang atom upang bumuo ng isang particle. Ano ang tawag dito?$$, $$A molecule consists of two or more atoms bonded together.$$ , $$Binubuo ang molecule ng dalawa o higit pang atom na magkakabigkis.$$ , $$[{"en":"Molecule","fil":"Molecule","correct":true},{"en":"Mixture","fil":"Mixture","correct":false},{"en":"Tissue","fil":"Tissue","correct":false},{"en":"Element symbol","fil":"Simbolo ng elemento","correct":false}]$$),
 ('starter-chemistry-solid', $$A material keeps its shape and volume because its particles are closely arranged. Which state is it in?$$, $$Nananatili ang hugis at volume ng materyal dahil magkakalapit ang mga particle nito. Anong estado ito?$$, $$A solid has a definite shape and a definite volume.$$ , $$May tiyak na hugis at volume ang solid.$$ , $$[{"en":"Solid","fil":"Solid","correct":true},{"en":"Liquid","fil":"Liquid","correct":false},{"en":"Gas","fil":"Gas","correct":false},{"en":"Plasma only","fil":"Plasma lamang","correct":false}]$$),
 ('starter-chemistry-liquid', $$A substance flows and takes the shape of its container but keeps a fixed volume. Which state is it?$$, $$Dumadaloy ang substance at sumusunod sa hugis ng lalagyan ngunit nananatili ang volume nito. Anong estado ito?$$, $$A liquid has a definite volume but takes the shape of its container.$$ , $$May tiyak na volume ang liquid ngunit sumusunod ito sa hugis ng lalagyan.$$ , $$[{"en":"Liquid","fil":"Liquid","correct":true},{"en":"Solid","fil":"Solid","correct":false},{"en":"Gas","fil":"Gas","correct":false},{"en":"Vacuum","fil":"Vacuum","correct":false}]$$),
 ('starter-chemistry-gas', $$Air spreads out to fill all the available space in a sealed container. Which state best describes its particles?$$, $$Kumakalat ang hangin upang punuin ang lahat ng espasyo sa saradong lalagyan. Anong estado ang naglalarawan sa mga particle nito?$$, $$A gas expands to fill its container and has no fixed shape or volume.$$ , $$Lumalawak ang gas upang punuin ang lalagyan at wala itong tiyak na hugis o volume.$$ , $$[{"en":"Gas","fil":"Gas","correct":true},{"en":"Solid","fil":"Solid","correct":false},{"en":"Liquid","fil":"Liquid","correct":false},{"en":"Crystal lattice only","fil":"Crystal lattice lamang","correct":false}]$$),
 ('starter-chemistry-melting', $$An ice cube absorbs heat and changes into liquid water. What change of state is taking place?$$, $$Sumisipsip ng init ang yelo at nagiging likidong tubig. Anong pagbabago ng estado ang nagaganap?$$, $$Melting changes a solid into a liquid.$$ , $$Ginagawang liquid ng melting ang solid.$$ , $$[{"en":"Melting","fil":"Pagkatunaw","correct":true},{"en":"Freezing","fil":"Pagyeyelo","correct":false},{"en":"Condensation","fil":"Condensation","correct":false},{"en":"Deposition","fil":"Deposition","correct":false}]$$),
 ('starter-chemistry-freezing', $$Liquid water loses heat and becomes ice. What change of state has occurred?$$, $$Nawawalan ng init ang likidong tubig at nagiging yelo. Anong pagbabago ng estado ang naganap?$$, $$Freezing changes a liquid into a solid.$$ , $$Ginagawang solid ng freezing ang liquid.$$ , $$[{"en":"Freezing","fil":"Pagyeyelo","correct":true},{"en":"Melting","fil":"Pagkatunaw","correct":false},{"en":"Evaporation","fil":"Pagsingaw","correct":false},{"en":"Sublimation","fil":"Sublimation","correct":false}]$$),
 ('starter-chemistry-evaporation', $$A puddle gradually disappears as liquid water becomes an invisible gas at its surface. What process is this?$$, $$Unti-unting nawawala ang tubig sa sahig habang nagiging di-nakikitang gas ang likido sa ibabaw nito. Anong proseso ito?$$, $$Evaporation changes liquid water into water vapor.$$ , $$Ginagawang singaw ng tubig ng evaporation ang likidong tubig.$$ , $$[{"en":"Evaporation","fil":"Pagsingaw o evaporation","correct":true},{"en":"Condensation","fil":"Condensation","correct":false},{"en":"Freezing","fil":"Pagyeyelo","correct":false},{"en":"Deposition","fil":"Deposition","correct":false}]$$),
 ('starter-chemistry-condensation', $$Water vapor cools on the outside of a cold glass and forms liquid droplets. What process caused them?$$, $$Lumalamig ang singaw ng tubig sa labas ng malamig na baso at nagiging patak ng likido. Anong proseso ang sanhi nito?$$, $$Condensation changes water vapor into liquid water.$$ , $$Ginagawang likidong tubig ng condensation ang singaw ng tubig.$$ , $$[{"en":"Condensation","fil":"Condensation","correct":true},{"en":"Evaporation","fil":"Pagsingaw","correct":false},{"en":"Melting","fil":"Pagkatunaw","correct":false},{"en":"Combustion","fil":"Combustion","correct":false}]$$),
 ('starter-chemistry-physical-change', $$A piece of wax melts but remains wax. No new substance forms. How is the change classified?$$, $$Natutunaw ang piraso ng wax ngunit wax pa rin ito. Walang bagong substance na nabuo. Paano inuuri ang pagbabago?$$, $$A physical change alters form or state without making a new substance.$$ , $$Binabago ng physical change ang anyo o estado ngunit hindi lumilikha ng bagong substance.$$ , $$[{"en":"Physical change","fil":"Pisikal na pagbabago","correct":true},{"en":"Chemical change","fil":"Kemikal na pagbabago","correct":false},{"en":"Nuclear reaction","fil":"Nuclear reaction","correct":false},{"en":"Formation of a new element","fil":"Pagbuo ng bagong elemento","correct":false}]$$),
 ('starter-chemistry-chemical-change', $$Iron reacts with oxygen and forms rust, a substance with different properties. What kind of change is this?$$, $$Tumutugon ang iron sa oxygen at bumubuo ng kalawang na may ibang katangian. Anong uri ng pagbabago ito?$$, $$A chemical change forms one or more new substances.$$ , $$Bumubuo ang chemical change ng isa o higit pang bagong substance.$$ , $$[{"en":"Chemical change","fil":"Kemikal na pagbabago","correct":true},{"en":"Physical change only","fil":"Pisikal na pagbabago lamang","correct":false},{"en":"Change in location","fil":"Pagbabago ng lokasyon","correct":false},{"en":"Change in container shape","fil":"Pagbabago ng hugis ng lalagyan","correct":false}]$$),
 ('starter-chemistry-periodic-table', $$A student looks for patterns among elements arranged by their atomic numbers. Which reference should they use?$$, $$Naghahanap ang mag-aaral ng mga padron sa mga elementong inayos ayon sa atomic number. Aling sanggunian ang dapat gamitin?$$, $$The periodic table organizes elements and reveals repeating patterns in their properties.$$ , $$Inaayos ng periodic table ang mga elemento at ipinakikita ang mga umuulit na padron sa mga katangian ng mga ito.$$ , $$[{"en":"Periodic table","fil":"Periodic table","correct":true},{"en":"Food web","fil":"Food web","correct":false},{"en":"Water cycle diagram","fil":"Dayagram ng siklo ng tubig","correct":false},{"en":"Number line","fil":"Number line","correct":false}]$$),
 ('starter-chemistry-atomic-number', $$An atom has 8 protons. What number identifies its element on the periodic table?$$, $$May 8 proton ang atom. Anong bilang ang tumutukoy sa elemento nito sa periodic table?$$, $$An element’s atomic number equals the number of protons in its atoms.$$ , $$Katumbas ng bilang ng proton sa mga atom nito ang atomic number ng elemento.$$ , $$[{"en":"8","fil":"8","correct":true},{"en":"The number of neutrons only","fil":"Bilang lamang ng neutron","correct":false},{"en":"The total number of electron shells","fil":"Kabuuang bilang ng electron shell","correct":false},{"en":"The atom’s mass in grams","fil":"Masa ng atom sa gramo","correct":false}]$$)
) AS v(content_key,quiz_en,quiz_fil,explanation_en,explanation_fil,options)
WHERE c.content_key=v.content_key;
